// packages/radar-domain/src/contracts/validation-datetime.ts
import { z as z2 } from "zod";
function contractDateTime(options = {}) {
  const suffix = options.offset ? "(?:Z|[+-]\\d{2}:?\\d{2})" : "Z";
  const pattern = new RegExp("^\\d{4}-\\d{2}-\\d{2}T(?:[01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d(?:\\.\\d+)?)?" + suffix + "$");
  const day = z2.iso.date();
  return z2.string().superRefine((value, ctx) => {
    if (!pattern.test(value) || !day.safeParse(value.slice(0, 10)).success) {
      ctx.addIssue({ code: "invalid_format", format: "datetime", message: "Invalid datetime" });
    }
  }).meta({ format: "date-time" });
}

