// packages/radar-domain/src/contracts/validation-number.ts
import { z as z23 } from "zod";
function contractInteger(options = {}) {
  const schema = options.coerce ? z23.coerce.number() : z23.number();
  return schema.refine(Number.isInteger, {
    message: "Expected integer, received float",
    params: { contract: {
      code: "invalid_type",
      expected: "integer",
      received: "float",
      message: "Expected integer, received float"
    } }
  });
}

